WITH filtered AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, ADD_MONTHS(launch_date, 1) AS launch_date_plus_months, COALESCE(brand, 'OTHER') AS resolved_brand FROM products WHERE brand IS NOT NULL AND supplier_id IN (11, 12, 16, 35)) SELECT id, product_name, category, brand, stock_qty, launch_date, launch_date_plus_months, LAG(cost) OVER (PARTITION BY brand ORDER BY cost, id) AS prev_cost, LEAD(price) OVER (PARTITION BY brand ORDER BY cost, id) AS next_price, ROW_NUMBER() OVER (PARTITION BY brand ORDER BY cost, id) AS seq_no, FIRST_VALUE(cost) IGNORE NULLS OVER (PARTITION BY category ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost FROM filtered;
